/* 兼容处理：针对部分不支持 zoom 的设备，使用 transform 等比例缩放并修正悬空留白 */
@supports not (zoom: 0.88) {
  #chat-detail-screen .msg-transfer-card,
  #chat-detail-screen .msg-redpacket-card,
  #chat-detail-screen .msg-loc-card {
    transform: scale(0.88) !important;
  }

  /* 我方发出的卡片靠右对齐，缩放基点设为右侧，并用负 margin 吃掉缩放产生的留白 */
  #chat-detail-screen .msg-me .msg-transfer-card,
  #chat-detail-screen .msg-me .msg-redpacket-card,
  #chat-detail-screen .msg-me .msg-loc-card {
    transform-origin: right center !important;
    margin-right: -6% !important; 
  }

  /* 对方发出的卡片靠左对齐，缩放基点设为左侧，并用负 margin 吃掉缩放产生的留白 */
  #chat-detail-screen .msg-them .msg-transfer-card,
  #chat-detail-screen .msg-them .msg-redpacket-card,
  #chat-detail-screen .msg-them .msg-loc-card {
    transform-origin: left center !important;
    margin-left: -6% !important; 
  }
}

/* ==========================================
   五、语音消息专属定制
   ========================================== */
:root {
  --voice-download-display: none; 
  --voice-toggle-display: flex;   
}

.voice-waveform {
  display: none !important;
}

.voice-controls-row {
  padding: 4px 6px !important;
  display: flex !important;
  align-items: center !important;
  gap: 12px !important; 
  background: transparent !important;
}

.voice-play-btn {
  width: auto !important;
  height: auto !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
}
.voice-play-btn svg { display: none !important; }

.voice-play-btn::after {
  content: "whisper"; 
  font-family: 'Times New Roman', serif;
  font-style: italic;
  font-size: 14px;
  letter-spacing: 1px;
  border-bottom: 1px solid rgba(38, 38, 38, 0.3);
  padding-bottom: 2px;
  transition: opacity 0.2s ease;
  cursor: pointer;
}
.voice-play-btn:active::after { opacity: 0.4; }

.voice-msg-me .voice-play-btn::after { color: #262626; border-bottom-color: rgba(38, 38, 38, 0.3); }
.voice-msg-them .voice-play-btn::after { color: #8e8e8e; border-bottom-color: rgba(142, 142, 142, 0.3); }

.voice-duration {
  font-family: 'Courier New', monospace !important;
  font-size: 12px !important;
  color: #8e8e8e !important;
  font-weight: 300 !important;
  letter-spacing: 1px !important;
  position: relative;
}
.voice-duration::before {
  content: "—";
  margin-right: 12px;
  color: #d0d0d0;
  font-weight: 100;
}

.voice-transcription-toggle {
  background: transparent !important;
  border: none !important;
  font-size: 0 !important; 
  padding: 0 !important;
  box-shadow: none !important;
}
.voice-transcription-toggle svg { display: none !important; }

.voice-transcription-toggle::after {
  content: "read"; 
  font-family: 'Times New Roman', serif;
  font-size: 12px;
  font-style: italic;
  color: #b0b0b0;
  letter-spacing: 1px;
  transition: color 0.2s ease;
}
.voice-transcription-toggle:hover::after { color: #8e8e8e; }

.voice-transcription {
  --voice-transcription-bg: transparent; 
  --voice-transcription-padding: 0 0 6px 0; 
  --voice-transcription-radius: 0;
  --voice-transcription-border: none;
  --voice-transcription-shadow: none;

  font-family: "STSong", "SimSun", serif !important; 
  font-size: 13px !important;
  color: #5C4D4D !important; 
  line-height: 1.6 !important;
  margin-top: 8px !important;
  border-bottom: 1px solid rgba(142, 142, 142, 0.2) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* ==========================================
   六、翻译功能专属定制
   ========================================== */
:root {
  --translation-always-show: 1;
}

.msg-translation-wrapper {
  display: none !important;
}

.msg-translation-detached {
  display: block !important;
  margin-top: 6px !important;
  width: fit-content !important;
  min-width: 100px !important; 
}

.msg-translation-detached-them { align-self: flex-start !important; }
.msg-translation-detached-me   { align-self: flex-end !important; }

.msg-translation-detached-content {
  background: transparent !important;
  color: #5C4D4D !important; 
  padding: 0 0 6px 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  font-family: "STSong", "SimSun", serif !important;
  font-size: 13px !important;
  line-height: 1.6 !important;
  border-bottom: 1px solid rgba(142, 142, 142, 0.2) !important;
}

.msg-translation-detached-content::before {
  content: "translate";
  display: block;
  font-family: 'Times New Roman', serif;
  font-size: 12px;
  font-style: italic;
  color: #b0b0b0;
  letter-spacing: 1px;
  margin-bottom: 6px;
}

/* ==========================================
   七、连发气泡净化
   ========================================== */
.msg-avatar-them-container,
.msg-avatar-me-container {
  visibility: hidden !important;
}

.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single,
.msg-avatar-me-container.is-first,
.msg-avatar-me-container.is-single {
  visibility: visible !important;
}

.bubble-them-custom::after,
.bubble-me-custom::after {
  display: none !important;
  content: none !important;
}

.msg-bubble-wrapper.is-first .bubble-them-custom:not(:has(.voice-msg)):not(:has(.msg-image-wrapper)):not(:has(.msg-image-card)):not(:has(.msg-transfer-card)):not(:has(.msg-loc-card)):not(:has(.msg-redpacket-card)):not(:has(.msg-theater-card)):not(:has(.msg-offline-invite-card))::after,
.msg-bubble-wrapper.is-single .bubble-them-custom:not(:has(.voice-msg)):not(:has(.msg-image-wrapper)):not(:has(.msg-image-card)):not(:has(.msg-transfer-card)):not(:has(.msg-loc-card)):not(:has(.msg-redpacket-card)):not(:has(.msg-theater-card)):not(:has(.msg-offline-invite-card))::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  left: -4.5px !important;
  top: 12px !important;
  width: 0 !important;
  height: 0 !important;
  border-top: 0px solid transparent !important;
  border-right: 6px solid #F4F4F6 !important;
  border-bottom: 8px solid transparent !important;
  transform: rotate(-6deg) !important;
  z-index: -1; 
}

.msg-bubble-wrapper.is-first .bubble-me-custom:not(:has(.voice-msg)):not(:has(.msg-image-wrapper)):not(:has(.msg-image-card)):not(:has(.msg-transfer-card)):not(:has(.msg-loc-card)):not(:has(.msg-redpacket-card)):not(:has(.msg-theater-card)):not(:has(.msg-offline-invite-card))::after,
.msg-bubble-wrapper.is-single .bubble-me-custom:not(:has(.voice-msg)):not(:has(.msg-image-wrapper)):not(:has(.msg-image-card)):not(:has(.msg-transfer-card)):not(:has(.msg-loc-card)):not(:has(.msg-redpacket-card)):not(:has(.msg-theater-card)):not(:has(.msg-offline-invite-card))::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  right: -4.5px !important;
  top: 12px !important;
  width: 0 !important;
  height: 0 !important;
  border-top: 0px solid transparent !important;
  border-left: 6px solid #f8e8f0 !important;
  border-bottom: 8px solid transparent !important;
  transform: rotate(6deg) !important;
  z-index: -1;
}

/* ==========================================
   八、思维链(Thinking) 终极单行极简定制
   ========================================== */
:root {
  --thinking-btn-bg: transparent;                      
  --thinking-btn-color: #8e8e8e;                       
  --thinking-btn-radius: 0px;
  --thinking-btn-padding: 0;                       
  --thinking-btn-font-size: 12px;
  --thinking-btn-shadow: none;                         
  --thinking-arrow-color: transparent;                 

  --thinking-panel-bg: transparent;                    
  --thinking-panel-padding: 6px 0 6px 12px;            
  --thinking-panel-radius: 0px;                        
  --thinking-panel-shadow: none;
  --thinking-panel-backdrop: none;
  --thinking-panel-border-left: 1px solid rgba(142, 142, 142, 0.25); 

  --thinking-text-color: #7a6e6e;                      
  --thinking-text-font-size: 12.5px;
  --thinking-text-font-style: italic;                  
  --thinking-text-line-height: 1.6;
}

.nuo-thinking-btn {
  display: inline-flex !important;
  align-items: center !important;
  flex-wrap: nowrap !important;
  width: auto !important;
  cursor: pointer !important;
  pointer-events: auto !important;
  position: relative !important;
}

.nuo-thinking-btn .nuo-thinking-icon,
.nuo-thinking-btn .nuo-thinking-label,
.nuo-thinking-btn svg,
.nuo-thinking-arrow {
  opacity: 0 !important;
  width: 0 !important;
  height: 0 !important;
  overflow: hidden !important;
  pointer-events: none !important;
}

.nuo-thinking-btn::after {
  content: "“in the quiet between words”"; 
  font-family: 'Times New Roman', serif;
  font-style: italic;
  font-size: 12px;
  color: #b0b0b0;
  letter-spacing: 0.5px;
  white-space: nowrap !important;
  cursor: pointer !important;
  pointer-events: auto !important;
  transition: color 0.2s ease;
  position: relative;
  z-index: 2;
}

.nuo-thinking-btn:hover::after {
  color: #8e8e8e;
}

/* ==========================================
   九、引用回复(Reply) 极简独立挂载定制
   ========================================== */
.msg-reply-block {
  display: none !important;
}

.msg-reply-block-detached {
  display: flex !important;
  flex-direction: column !important; 
  align-items: flex-start !important;
  margin-top: 6px !important;
  margin-bottom: 2px !important;
  width: fit-content !important;
  max-width: 80vw !important; 
  box-sizing: border-box !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
}

.msg-reply-detached-them { align-self: flex-start !important; }
.msg-reply-detached-me   { align-self: flex-end !important; }

.msg-reply-detached-text {
  background: transparent !important;
  color: #5C4D4D !important; 
  padding: 0 0 6px 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  font-family: "STSong", "SimSun", serif !important;
  font-size: 13px !important;
  line-height: 1.6 !important;
  word-break: break-all !important; 
  overflow-wrap: break-word !important;
  white-space: pre-wrap !important;
  max-width: 100% !important;
  border-bottom: 1px solid rgba(142, 142, 142, 0.2) !important;
}

.msg-reply-detached-media {
  display: none !important;
}

.msg-reply-detached-text::before {
  content: "reference";
  display: block;
  font-family: 'Times New Roman', serif;
  font-size: 12px;
  font-style: italic;
  color: #b0b0b0;
  letter-spacing: 1px;
  margin-bottom: 4px;
}

.msg-reply-detached-name {
  display: none !important; 
}

/* ==========================================
   十、控制台与底栏水印 (MOONLIGHT) 完美重合
   ========================================== */
.nuo-console-shell {
  position: relative !important;
  width: 100% !important;
  margin-top: 0 !important;
}

.nuo-console-toggle-row {
  position: absolute !important;
  top: -55px !important;     
  left: 20px !important;     
  width: 220px !important;   
  height: 35px !important;   
  margin: 0 !important;
  opacity: 0 !important;     
  z-index: 20 !important;    
  cursor: pointer !important;
}

.nuo-console-toggle-btn,
.nuo-console-token-btn {
  width: 100% !important;
  height: 100% !important;
  opacity: 0 !important;
  cursor: pointer !important;
}

.chat-detail-screen {
  --console-panel-bg: #ffffff;
  --console-panel-color: #262626;
  --console-panel-border: 1px solid rgba(0, 0, 0, 0.08);
  --console-panel-radius: 12px;
  --console-panel-shadow: 0 10px 30px rgba(0, 0, 0, 0.08);
  --console-entry-warn-color: #bfa15f;
  --console-entry-error-color: #d97d7d;
  --console-entry-border: 1px solid rgba(0, 0, 0, 0.05);
}

/* ==========================================
   十一、特殊卡片 (转账/红包/地点) 极简重构
   ========================================== */
/* 1. 彻底抽空原生卡片的底板、边框和阴影 */
.msg-transfer-card,
.msg-redpacket-card,
.msg-loc-card {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  padding: 0 0 6px 0 !important;
  margin-top: 6px !important;
  border-bottom: 1px solid rgba(142, 142, 142, 0.2) !important;
  display: flex !important;
  flex-direction: column !important;
}

/* 2. 强行统一内部文字风格，排除定位针以免滤镜和背景被误杀 */
.msg-transfer-card *,
.msg-redpacket-card *,
.msg-loc-card *:not(.msg-loc-pin-wrapper):not(.msg-loc-pin-circle):not(.msg-loc-pin-shadow):not(.msg-loc-pin-wrapper *) {
  font-family: "STSong", "SimSun", serif !important;
  color: #5C4D4D !important;
  background-color: transparent !important; 
  box-shadow: none !important;
  border: none !important;
}

/* 3. 隐藏原生突兀的 SVG 图标 */
.msg-transfer-card svg,
.msg-redpacket-emoji {
  display: none !important;
}
/* 4. 拯救地图：换黑针，去红圈，加黑线网格 */
:root {
  --location-pin-color: #262626; 
}

/* 释放被隐藏的定位针，彻底抽空原本的红色圆形底板和发光，只保留纯净形状 */
.msg-loc-pin-circle {
  display: flex !important;
  background: transparent !important;
  box-shadow: none !important;
}

.msg-loc-pin-circle svg {
  fill: #262626 !important;
  color: #262626 !important;
}

/* 清除之前残余的暴力滤镜，只加轻微阴影 */
.msg-loc-pin-wrapper {
  filter: drop-shadow(0 2px 4px rgba(0,0,0,0.15)) !important;
}

/* 锁定定位针的父容器(地图框)，画上黑色细线网格 */
.msg-loc-card div:has(> .msg-loc-pin-wrapper) {
  position: relative !important;
  min-height: 120px !important;
  background-color: #fafafa !important;
  background-image: 
    linear-gradient(rgba(0, 0, 0, 0.15) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 0, 0, 0.15) 1px, transparent 1px) !important;
  background-size: 14px 14px !important;
  border-radius: 8px !important;
  margin: 8px 0 !important;
  border: 1px solid rgba(0, 0, 0, 0.05) !important;
  overflow: hidden !important;
}

/* 5. 注入极简英文表头 */
.msg-transfer-card:not(.msg-redpacket-card)::before {
  content: "transfer";
  display: block;
  font-family: 'Times New Roman', serif;
  font-size: 12px;
  font-style: italic;
  color: #b0b0b0;
  letter-spacing: 1px;
  margin-bottom: 4px;
}

.msg-redpacket-card::before {
  content: "gift";
  display: block;
  font-family: 'Times New Roman', serif;
  font-size: 12px;
  font-style: italic;
  color: #b0b0b0;
  letter-spacing: 1px;
  margin-bottom: 4px;
}

.msg-loc-card::before {
  content: "location";
  display: block;
  font-family: 'Times New Roman', serif;
  font-size: 12px;
  font-style: italic;
  color: #b0b0b0;
  letter-spacing: 1px;
  margin-bottom: 4px;
}

/* ==========================================
   十二、潜台词 (Subtext) 极简独立定制
   ========================================== */
.msg-subtext-chip {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

.msg-subtext-toggle {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  font-size: 0 !important;
  margin-bottom: 4px !important;
}

.msg-subtext-toggle svg {
  display: none !important;
}

.msg-subtext-toggle::after {
  content: "subtext";
  display: block;
  font-family: 'Times New Roman', serif;
  font-size: 12px;
  font-style: italic;
  color: #b0b0b0;
  letter-spacing: 1px;
  transition: color 0.2s ease;
}

.msg-subtext-toggle:hover::after {
  color: #8e8e8e;
}

.msg-subtext-body {
  background: transparent !important;
  color: #5C4D4D !important;
  padding: 0 0 6px 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  font-family: "STSong", "SimSun", serif !important;
  font-size: 13px !important;
  line-height: 1.6 !important;
  border-bottom: 1px solid rgba(142, 142, 142, 0.2) !important;
}

/* ==========================================
   十八、气泡小尾巴无缝贴合与真正上翘补丁 (修正版)
   ========================================== */

/* 1. 调整对方（左侧）小尾巴：往里收缩，顺时针转动(正角度)让尖端上翘 */
#chat-detail-screen .bubble-them-custom::after {
  left: -4px !important;               /* 往本体内收缩，吃掉缝隙 */
  top: 12px !important;                
  transform: rotate(8deg) !important;  /* 改为正角度，尾巴尖端向上翘起贴合 */
}

/* 2. 调整我方（右侧）小尾巴：往里收缩，逆时针转动(负角度)让尖端上翘 */
#chat-detail-screen .bubble-me-custom::after {
  right: -4px !important;              /* 往本体内收缩，吃掉缝隙 */
  top: 12px !important; 
  transform: rotate(-8deg) !important; /* 改为负角度，尾巴尖端向上翘起贴合 */
}
/* ==========================================
   二十、全局字体统一剥离补丁 (一键覆盖版)
   说明：粘贴在 CSS 最底部。强行剥离所有手写字体，
   使其全部完美继承糯叽机 APP 外观设置中的全局字体。
   ========================================== */

/* 1. 批量覆盖所有被写死字体的自定义元素和伪元素 */
#chat-detail-screen .chat-header-title,
#chat-detail-screen .header-btn-back::before,
#chat-detail-screen .header-btn-phone::after,
#chat-detail-screen .header-btn-video::after,
#chat-detail-screen .header-btn-info::after,
#chat-detail-screen .input-area-custom::before,
#chat-detail-screen .input-box-custom,
#chat-detail-screen .input-btn-mic::after,
#chat-detail-screen .input-btn-sticker::after,
#chat-detail-screen .input-btn-ai::after,
#chat-detail-screen .send-btn-custom::after,
#chat-detail-screen .voice-play-btn::after,
#chat-detail-screen .voice-duration,
#chat-detail-screen .voice-transcription-toggle::after,
#chat-detail-screen .voice-transcription,
#chat-detail-screen .msg-translation-detached-content,
#chat-detail-screen .msg-translation-detached-content::before,
#chat-detail-screen .nuo-thinking-btn::after,
#chat-detail-screen .msg-reply-detached-text,
#chat-detail-screen .msg-reply-detached-text::before,
#chat-detail-screen .msg-transfer-card *,
#chat-detail-screen .msg-transfer-card::before,
#chat-detail-screen .msg-redpacket-card *,
#chat-detail-screen .msg-redpacket-card::before,
#chat-detail-screen .msg-loc-card *,
#chat-detail-screen .msg-loc-card::before,
#chat-detail-screen .msg-subtext-toggle::after,
#chat-detail-screen .msg-subtext-body {
  font-family: inherit !important;
}

/* 2. 还原输入框原生占位符 (剥离写死字体的 SVG 图片伪装) */
#chat-detail-screen .input-box-custom {
  background-image: none !important;
}
#chat-detail-screen .input-box-custom::-webkit-input-placeholder {
  color: rgba(150, 150, 150, 0.7) !important; /* 兼容日夜间的自然中性灰 */
}
#chat-detail-screen .input-box-custom::placeholder {
  color: rgba(150, 150, 150, 0.7) !important;
}

