/* ============================================================
   ⑦ 输入栏上方的提示条(沿用第二套)
   ============================================================ */
:root {
  --tip-bg: rgba(255, 255, 255, 0.88);
  --tip-border: 1px solid #e2e2e2;
  --tip-radius: 10px;            /* 四角圆润程度,想更方就调小 */
  --tip-color: #9a9a9a;
  --tip-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
  --tip-gap: 6px;                /* 条与条之间的距离 */
  --tip-pad: 8px 12px;
}

:root {
  --tip-gap: 8px;
  /* 各条的大概高度,只用来算"往上叠多少",不是固定高度 */
  --h-reply: 46px;
  --h-sendas: 38px;
  --h-qrai: 70px;
}

/* ① 底栏作为定位基准,提示条悬浮在它上方 */
.chat-detail-screen .input-area-custom {
  position: relative !important;
  overflow: visible !important;
  /* 记录当前有哪些条在,用来算叠放高度 */
  --r: 0; --s: 0; --q: 0;
}
.input-area-custom:has(.input-reply-preview-bar) { --r: 1; }
.input-area-custom:has(.input-sendas-bar)        { --s: 1; }
.input-area-custom:has(.nuo-qrai-hint, .nuo-qrai-panel) { --q: 1; }

.input-reply-preview-bar,
.input-sendas-bar,
.nuo-qrai-hint,
.nuo-qrai-panel,
.nuo-console-shell {
  position: absolute !important;
  left: 14px !important;
  right: 14px !important;
  top: auto !important;
  margin: 0 !important;
  height: auto !important;          /* 高度跟内容走 */
  max-height: none !important;
  transform: none !important;
  z-index: 30 !important;
}

/* 从下往上依次:引用预览 → 发送身份/旁白 → AI 回覆建议 → 控制台 */
.input-reply-preview-bar {
  bottom: calc(100% + var(--tip-gap)) !important;
}
.input-sendas-bar {
  bottom: calc(100% + var(--tip-gap) + var(--r) * (var(--h-reply) + var(--tip-gap))) !important;
}
.nuo-qrai-hint,
.nuo-qrai-panel {
  bottom: calc(100% + var(--tip-gap)
    + var(--r) * (var(--h-reply) + var(--tip-gap))
    + var(--s) * (var(--h-sendas) + var(--tip-gap))) !important;
}
.nuo-console-shell {
  bottom: calc(100% + var(--tip-gap)
    + var(--r) * (var(--h-reply) + var(--tip-gap))
    + var(--s) * (var(--h-sendas) + var(--tip-gap))
    + var(--q) * (var(--h-qrai) + var(--tip-gap))) !important;
}

/* ② 引用预览:去掉前面的竖杠 */
.chat-detail-screen {
  --reply-bar-accent-border: none;
  --reply-bar-content-padding-left: 0px;
}
.input-reply-preview-bar,
.input-reply-preview-content,
.input-reply-preview-name,
