/* ============================================================
   ⑧ 翻译:隐藏「查看翻译」,点气泡展开 → 白字黑描边(沿用第二套)
   ============================================================ */

/* 1. 气泡内:翻译区脱离排版流,不占任何高度 */
.msg-translation-wrapper {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  overflow: visible !important;
  pointer-events: none !important;   /* 自己不挡点击,只让里面的按钮接收 */
  z-index: 3 !important;
}
.msg-translation-wrapper .msg-translation-content {
  display: none !important;
}

/* 2. 按钮:不可见,但铺满整个气泡,可点击 */
.bubble-them-custom,
.bubble-me-custom {
  position: relative !important;
}
.msg-translation-btn {
  display: block !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  font-size: 0 !important;
  color: transparent !important;
  opacity: 1 !important;
  overflow: hidden !important;
  cursor: pointer !important;
  pointer-events: auto !important;
  z-index: 3 !important;
}
.msg-translation-btn *,
.msg-translation-btn svg,
.msg-translation-btn span {
  display: none !important;
}
.msg-translation-btn::before,
.msg-translation-btn::after {
  display: none !important;
  content: none !important;
}
.bubble-them-custom,
.bubble-me-custom {
  position: relative !important;
  gap: 0 !important;
  row-gap: 0 !important;
}

/* 3. 气泡外:点开后出现的独立翻译块 */
.msg-translation-detached {
  display: block !important;
  margin-top: 6px !important;
  max-width: 100% !important;
  width: fit-content !important;
  min-width: 0 !important;
  box-sizing: border-box !important;
}

/* 4. 内容层(会被下面第 5 段覆盖成纯文字) */
.msg-translation-detached-content {
  background: #ffffff !important;
  color: #1D1B37 !important;
  padding: 5px 16px !important;
  border: 1.5px solid #1D1B37 !important;
  border-radius: 10px !important;
  box-shadow: 0 2px 6px rgba(29,27,55,0.06) !important;
  font-size: 13px !important;
  line-height: 1.5 !important;
  word-break: break-word !important;
  position: relative !important;
}
.msg-translation-detached-me .msg-translation-detached-content {
  background: #FFF4FA !important;
}

/* 5. 翻译文字:去气泡,粗体 + 白字黑描边 */
.msg-translation-detached-content,
.msg-translation-detached-me .msg-translation-detached-content,
.msg-translation-detached-them .msg-translation-detached-content {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 2px 0 !important;
  font-size: 13px !important;
  font-weight: 700 !important;
  line-height: 1.5 !important;
  letter-spacing: 0.5px !important;
  word-break: break-word !important;
  position: relative !important;

  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  -webkit-text-stroke: 2.5px #1D1B37 !important;
  paint-order: stroke fill !important;
  text-shadow: none !important;
}

/* 我方靠右 */
.msg-translation-detached-me .msg-translation-detached-content {
  text-align: right !important;
}

/* ===== 翻译文字:上移 + 右移,悬浮在气泡边缘 ===== */
.msg-translation-detached {
  margin-top: -4px !important;
  position: relative !important;
  z-index: 6 !important;
  pointer-events: none !important;
}

/* 对方:往上、往右 */
.msg-translation-detached-them {
  transform: translate(18px, -10px) !important;
}

/* 我方:往上,向左浮 */
.msg-translation-detached-me {
  transform: translate(-18px, -10px) !important;
}

