/* 图片:固定比例 + 后两层用图床图片 */
:root {
  --img-w: 160px;          /* 实体图宽度 */
  --img-ratio: 3 / 4;      /* 4:3 横图;想要竖图就改成 3 / 4 */
  --st-r: 16px;            /* 圆角 */

  --st-gap1: 9px;          /* 第二层往右露出多少 */
  --st-gap2: 18px;         /* 第三层往右露出多少 */
  --st-in1: 8px;           /* 第二层上下各缩进多少 */
  --st-in2: 16px;          /* 第三层上下各缩进多少 */

  /* ★ 把两个链接换成你图床里的图 */

  --st-img1: url("https://imgbed.heliar.top/i/HPLqCkpwxlWeZW0k_IMG_0399.jpeg");
  --st-img2: url("https://imgbed.heliar.top/i/XKCH-a3_6FymY_Ft_IMG_0397.jpeg");

  --st-f1: none;
  --st-f2: none;

}
body.dark-mode {
  --st-f1: grayscale(0.5) blur(1.5px) brightness(0.6);
  --st-f2: grayscale(0.9) blur(2.5px) brightness(0.45);
}

/* 实体图卡片:固定大小 */
.msg-image-wrapper,
.msg-image-card {
  position: relative !important;
  isolation: isolate !important;
  width: var(--img-w) !important;
  max-width: 100% !important;
  height: auto !important;
  aspect-ratio: var(--img-ratio) !important;
  box-shadow: none !important;
  border-radius: var(--st-r) !important;
  margin: 0 calc(var(--st-gap2) + 2px) 0 0 !important;
}
body .chat-detail-screen .msg-image-wrapper > *,
body .chat-detail-screen .msg-image-card > * {
  width: 100% !important;
  height: 100% !important;
}
body .chat-detail-screen .msg-image-wrapper img,
body .chat-detail-screen .msg-image-card img {
  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  max-height: none !important;
  object-fit: cover !important;
  border-radius: var(--st-r) !important;
}

/* 后两层 */
.msg-image-wrapper::before,
.msg-image-card::before,
.msg-image-wrapper::after,
.msg-image-card::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  border-radius: var(--st-r) !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  pointer-events: none !important;
}
.msg-image-wrapper::before,
.msg-image-card::before {
  top: var(--st-in1) !important;
  bottom: var(--st-in1) !important;
  left: var(--st-gap1) !important;
  right: calc(-1 * var(--st-gap1)) !important;
  background-image: var(--st-img1) !important;
  filter: var(--st-f1) !important;
  z-index: -1 !important;
}
.msg-image-wrapper::after,
.msg-image-card::after {
  top: var(--st-in2) !important;
  bottom: var(--st-in2) !important;
  left: var(--st-gap2) !important;
  right: calc(-1 * var(--st-gap2)) !important;
  background-image: var(--st-img2) !important;
  filter: var(--st-f2) !important;
  z-index: -2 !important;
}
/* 实体图:盖过表情包的 110px 限制,并给固定高度 */
