  content: "Send" !important;
  color: var(--theme-send-active-color) !important;
  font-size: 13px !important;
  font-weight: 600 !important;
}

/* ============================================================
   4. 头像与顶语气泡
   ============================================================ */

.msg-avatar-custom,
.msg-avatar-them-container,
.msg-avatar-them-inner,
.msg-avatar-them-inner img,
.msg-avatar-me-container,
.msg-avatar-me-inner,
.msg-avatar-me-inner img,
.msg-avatar-container,
.msg-avatar-container img {
  border-radius: 50% !important;
  overflow: hidden !important;
}

.msg-avatar-them-container,
.msg-avatar-container {
  position: relative !important;
  overflow: visible !important;
}

/* 首行消息整行整体物理下沉避让 */
.msg-bubble-wrapper.is-first,
.msg-bubble-wrapper.is-single,
.msg-them.is-first,
.msg-them.is-single,
.msg-bubble-wrapper[data-first="true"] {
  padding-top: 32px !important;
  position: relative !important;
  box-sizing: border-box !important;
}

.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single,
.msg-them.is-first .msg-avatar-them-container {
  padding-top: 0 !important;
  position: relative !important;
  overflow: visible !important;
}

/* 白色小对话气泡「ㅠ⩊ㅠ」 */
.msg-avatar-them-container.is-first::before,
.msg-avatar-them-container.is-single::before,
.msg-them.is-first .msg-avatar-them-container::before,
[data-first="true"] .msg-avatar-them-container::before {
  content: "ㅠ⩊ㅠ" !important;
  position: absolute !important;
  top: -26px !important;
  bottom: auto !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
  background: #ffffff !important;
  color: #1a1a1a !important;
  font-size: 11px !important;
  font-weight: 600 !important;
  line-height: 1.2 !important;
  padding: 3px 8px !important;
  border-radius: 8px !important;
  white-space: nowrap !important;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.15) !important;
  z-index: 10 !important;
  pointer-events: none !important;
}

/* 白色朝下小尖角 */
.msg-avatar-them-container.is-first::after,
.msg-avatar-them-container.is-single::after,
.msg-them.is-first .msg-avatar-them-container::after,
[data-first="true"] .msg-avatar-them-container::after {
  content: "" !important;
  position: absolute !important;
  top: -7px !important;
  bottom: auto !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
  width: 0 !important;
  height: 0 !important;
  border-left: 5px solid transparent !important;
  border-right: 5px solid transparent !important;
  border-top: 6px solid #ffffff !important;
  z-index: 10 !important;
  pointer-events: none !important;
}

.msg-avatar-them-container.is-mid::before,
.msg-avatar-them-container.is-mid::after,
.msg-avatar-them-container.is-last::before,
.msg-avatar-them-container.is-last::after {
  display: none !important;
}

