.msg-image-wrapper::before,
.msg-transfer-card::before,
.msg-loc-card::before,
.msg-theater-card::before,
.msg-offline-invite-card::before,
.gift-ig-container::before,
.msg-sim-card::before {
  display: none !important;
}

